def read_fasta(path):
    with open(path) as f:
        return "".join(l.strip() for l in f if not l.startswith(">")).upper()

s = read_fasta("region.fasta")
comp = str.maketrans("ACGT", "TGCA")
def revcomp(x): return x.translate(comp)[::-1]

stops = {"TAA","TAG","TGA"}
starts = {"ATG"}

def find_orfs(seq, minlen=60):
    """Return list of (frame, dna_start0based, dna_end0based_exclusive, strand, prot_len)
    ORF = start codon -> stop codon inclusive of stop; also allow truncated-at-end ORFs."""
    res = []
    L = len(seq)
    for strand in ("+","-"):
        ss = seq if strand=="+" else revcomp(seq)
        for frame in range(3):
            i = frame
            while i + 2 < L:
                codon = ss[i:i+3]
                if codon in starts:
                    j = i+3
                    prot = 0
                    while j+2 < L:
                        c = ss[j:j+3]
                        if c in stops:
                            if prot >= minlen//3:
                                res.append((strand, frame, i, j+3, prot))
                            i = j  # jump to next in-frame position after this stop
                            break
                        j += 3
                        prot += 1
                    else:
                        # no stop found: ORF runs to end of sequence
                        if prot >= minlen//3:
                            res.append((strand, frame, i, L, prot))
                        i = j
                        continue
                    continue
                i += 3
    return res

