comp = str.maketrans("ACGT","TGCA")
def revcomp(x): return x.translate(comp)[::-1]
rcs = revcomp(s)
codon_table={}
bases="TCAG"; aas="FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG"
i=0
for b1 in bases:
    for b2 in bases:
        for b3 in bases:
            codon_table[b1+b2+b3]=aas[i]; i+=1
def translate(nt): return "".join(codon_table.get(nt[i:i+3],"X") for i in range(0,len(nt)-2,3))
stops = {"TAA","TAG","TGA"}
L = len(s)

def scan(seq_strand, start_pos, want_ORF=True, min_aa=20):
    """Scan a single frame forward from start_pos, return ORFs starting at ATG.
       orf起点 at start_pos, walks forward."""
    out = []
    i = start_pos
    while i + 2 < len(seq_strand):
        if seq_strand[i:i+3] == "ATG":
            j = i + 3
            a = i
            found_stop = None
            while j + 2 < len(seq_strand):
                if seq_strand[j:j+3] in stops:
                    found_stop = j
                    break
                j += 3
            if found_stop is not None and (found_stop - a)//3 >= min_aa:
                out.append((a, found_stop+3))     # [a, stop_end)
            i = a + 3  # advance past this start, allow overlapping starts
        else:
            i += 3
    return out

all_orfs = []
for strand_name, seq in [("+", s), ("-", rcs)]:
    for frame in range(3):
        for a_stop in scan(seq, frame):
            a, b = a_stop
            all_orfs.append((strand_name, a, b))

def display_coords(strand, a, b):
    return (a+1, b) if strand=="+" else (L-b+1, L-a)

print("All ORFs (ATG→stop) with min aa >= 20:")
rows = []
